"""
CI audit of every uv.lock in the repository (job `python-dependency-audit`).

For each project directory that has a tracked `uv.lock` (found with `git ls-files`, never from a
hand-kept list) it:

1. runs `uv lock --check`, which fails when the lock disagrees with pyproject.toml;
2. requires every tracked top-level `requirements*.txt` or `requirements*.lock` in the directory to be a uv export (its
   header names the `uv export` command that produced it), regenerates each one and fails when its
   content changes, which means the export was stale (the file is left regenerated, so a local run
   fixes it). A requirements file without the header fails: a hand-written file beside a lock would
   otherwise be installed without being checked or audited;
3. audits each export with pip-audit and fails on every advisory that is not on the allowlist
   `.github/python-audit-allowlist.json`. A requirement installed from a direct URL cannot be audited by
   pip-audit; it is left out of the file pip-audit reads and named in the job summary.

The allowlist is validated first: every entry needs `id`, `package`, `reason` and a `reviewBy` date
(ISO, not in the past). An entry that matches no current finding is stale and also fails the run.
A pip-audit run that cannot reach the advisory service fails the run; it never passes silently.

Only package names, versions and advisory ids are printed or written to the job summary.
Standard library only. Needs `uv` on PATH and the environment variable PIP_AUDIT_VERSION.
"""

import argparse
import datetime
import json
import os
import re
import shlex
import subprocess
import sys
import tempfile

ALLOWLIST_PATH = ".github/python-audit-allowlist.json"
EXEMPTIONS_PATH = ".github/python-lock-exemptions.json"
EXPORT_HEADER = "# This file was autogenerated by uv via the following command:"
# `uv export` flags an export header may carry. Anything else is refused, because the header is
# read from a file in the repository and then run. `--no-header` is refused: the header is required.
ALLOWED_EXPORT_FLAGS = {
    "--frozen",
    "--no-hashes",
    "--no-emit-project",
    "--no-dev",
    "--no-annotate",
    "--all-groups",
}
ALLOWED_EXPORT_VALUE_FLAGS = {"--group", "--only-group", "--no-group", "--extra", "--no-extra", "--no-emit-package"}
ID_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
# Top-level files in a locked directory that must be uv exports. A `requirements*.lock` is the file a
# container Dockerfile installs with `pip install --require-hashes`: a hashed export, not a second source.
REQUIREMENTS_FILE = re.compile(r"^requirements[^/]*\.(txt|lock)$")
PIP_AUDIT_STRICT_ARGS = ["--no-deps", "--disable-pip", "--strict", "--progress-spinner", "off"]


class AuditError(Exception):
    """A condition that fails the job."""


def escape_data(text):
    """A workflow-command message: `%`, `\r` and `\n` escaped as GitHub requires."""
    return str(text).replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A")


def escape_property(text):
    """A workflow-command property value (`title=`): the message escapes plus `:` and `,`."""
    return escape_data(text).replace(":", "%3A").replace(",", "%2C")


def error(title, message):
    print(f"::error title={escape_property(title)}::{escape_data(message)}")


def canonical_name(name):
    """PEP 503 normalised package name, so `typing_extensions` matches `typing-extensions`."""
    return re.sub(r"[-_.]+", "-", str(name)).lower()


def last_line(text):
    """The last non-empty line of a tool's stderr: the error, without the traceback above it."""
    lines = [line.strip() for line in str(text).splitlines() if line.strip()]
    return lines[-1] if lines else "(no output)"


def run(command, cwd, check=True):
    try:
        result = subprocess.run(command, cwd=cwd, capture_output=True, text=True)
    except FileNotFoundError:
        raise AuditError(f"`{command[0]}` is not on PATH; install it before running the audit")
    if check and result.returncode != 0:
        raise AuditError(
            f"`{' '.join(command)}` failed in {cwd or '.'} (exit {result.returncode}):\n"
            f"{result.stdout.strip()}\n{result.stderr.strip()}".strip()
        )
    return result


def tracked_files(root):
    out = run(["git", "ls-files", "-z"], root).stdout
    return [p for p in out.split("\0") if p]


def read_export_command(path):
    """The `uv export` argument list from an export file's header, or None if it is not an export."""
    try:
        with open(path, encoding="utf-8") as handle:
            head = [handle.readline() for _ in range(3)]
    except UnicodeDecodeError:
        raise AuditError(f"{path}: not UTF-8 text")
    if head[0].strip() != EXPORT_HEADER:
        return None
    line = head[1].strip()
    if not line.startswith("#"):
        raise AuditError(f"{path}: the export header has no command line")
    try:
        words = shlex.split(line.lstrip("# ").strip())
    except ValueError as exc:
        raise AuditError(f"{path}: the export header command cannot be parsed ({exc})")
    if words[:2] != ["uv", "export"]:
        raise AuditError(f"{path}: the export header command is not `uv export`")
    args = words[2:]
    output = None
    checked = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-o", "--output-file"):
            if i + 1 >= len(args):
                raise AuditError(f"{path}: `{arg}` has no value in the export header")
            output = args[i + 1]
            i += 2
        elif arg in ALLOWED_EXPORT_FLAGS:
            checked.append(arg)
            i += 1
        elif arg in ALLOWED_EXPORT_VALUE_FLAGS and i + 1 < len(args):
            checked.extend([arg, args[i + 1]])
            i += 2
        else:
            raise AuditError(f"{path}: the export header uses `{arg}`, which this audit does not allow")
    if output is None or os.path.basename(output) != output or output != os.path.basename(path):
        raise AuditError(f"{path}: the export header must write the file it sits in (`-o {os.path.basename(path)}`)")
    return checked


def load_allowlist(root, today):
    path = os.path.join(root, ALLOWLIST_PATH)
    try:
        with open(path, encoding="utf-8") as handle:
            data = json.load(handle)
    except (OSError, ValueError) as exc:
        raise AuditError(f"{ALLOWLIST_PATH} is not readable JSON: {exc}")
    entries = data.get("entries") if isinstance(data, dict) else None
    if not isinstance(entries, list):
        raise AuditError(f'{ALLOWLIST_PATH} must be an object with an "entries" list')
    problems = []
    seen = set()
    for index, entry in enumerate(entries):
        label = f"entry {index}"
        if not isinstance(entry, dict):
            problems.append(f"{label} is not an object")
            continue
        label = f"entry {index} ({entry.get('id')})"
        for key in ("id", "package", "reason", "reviewBy"):
            if not isinstance(entry.get(key), str) or not entry[key].strip():
                problems.append(f"{label} has no {key}")
        if isinstance(entry.get("id"), str) and not ID_PATTERN.match(entry["id"]):
            problems.append(f"{label} has an invalid id")
        key = (str(entry.get("id")).lower(), canonical_name(entry.get("package")))
        if key in seen:
            problems.append(f"{label} is listed twice")
        seen.add(key)
        if isinstance(entry.get("reviewBy"), str) and entry["reviewBy"].strip():
            try:
                review_by = datetime.date.fromisoformat(entry["reviewBy"])
            except ValueError:
                problems.append(f"{label} reviewBy is not an ISO date")
            else:
                if review_by < today:
                    problems.append(
                        f"{label} reviewBy {entry['reviewBy']} is in the past: review it, then fix or extend it"
                    )
    if problems:
        raise AuditError(f"{ALLOWLIST_PATH} is invalid:\n  " + "\n  ".join(problems))
    return entries


# Files that can install a requirements file: Dockerfiles, CI and recipe YAML, shell scripts, and the
# CDK code that runs bundling commands. Tests and docs only mention paths, so they are not scanned.
# Files that can install a requirements file: Dockerfiles, CI and recipe YAML, shell, Python and TOML/JSON
# command files, and the CDK code that runs bundling commands. Tests and docs only mention paths, so they
# are not scanned; neither are lock files, the package manager's own lock JSON or this exemption file.
INSTALLER_FILE = re.compile(
    r"(^|/)(Dockerfile[^/]*|makefile|Makefile|[^/]+\.(ya?ml|sh|bash|ts|py|toml|json))$"
)
INSTALLER_SKIP = re.compile(
    r"(^|/)(test|tests|node_modules|cdk\.out)/|\.d\.ts$|^documentation/|^planning/"
    r"|(^|/)(package-lock|npm-shrinkwrap|tsconfig[^/]*|cdk)\.json$|^\.github/python-lock-exemptions\.json$"
)
INSTALL_VERB = re.compile(
    r"([\s'\"\[,]-r[\s'\",\]]|--requirement|\bCOPY\b|\bADD\b|\bpip3?['\"\s,]+(install|download)\b|\buv['\"\s,]+pip\b|\bcp\b)"
)


def _flat(text):
    return re.sub(r"[^a-z0-9]", "", text.lower())


def logical_lines(text):
    """(first line number, text) of each line, with backslash continuations joined, as a shell reads them."""
    result = []
    pending, start = [], 0
    for number, line in enumerate(text.splitlines()):
        if not pending:
            start = number
        stripped = line.rstrip()
        if stripped.endswith("\\"):
            pending.append(stripped[:-1])
            continue
        pending.append(line)
        result.append((start, " ".join(part.strip() for part in pending)))
        pending = []
    if pending:
        result.append((start, " ".join(part.strip() for part in pending)))
    return result


def requirement_names(path, text):
    """Distribution names a ranged file declares: requirements lines, or setup.py's quoted specifiers."""
    names = set()
    if os.path.basename(path) == "setup.py":
        # The install_requires list and the lists inside extras_require; the extras' own keys are not packages.
        region = re.search(r"install_requires\s*=.*?(?=entry_points|classifiers|python_requires|\Z)", text, re.S)
        for block in re.findall(r"\[([^\]]*)\]", region.group(0) if region else ""):
            for spec in re.findall(r"""['"]([A-Za-z0-9][A-Za-z0-9._-]*)\s*(?:[<>=!~;].*?)?['"]""", block):
                names.add(canonical_name(spec))
        return names
    for line in text.splitlines():
        line = line.split("#")[0].strip()
        match = re.match(r"^([A-Za-z0-9][A-Za-z0-9._-]*)", line)
        if match and not line.startswith("-"):
            names.add(canonical_name(match.group(1)))
    return names


def locked_names(lock_text):
    return {canonical_name(n) for n in re.findall(r'^name = "([^"]+)"', lock_text, re.M)}


def installers_of(root, tracked, target):
    """Files that install or copy `target` (a repository path): returns [(file, line number)].

    A reference counts when the installing line names the file's basename in an install, COPY or cp
    command and the path is any of: the full repository path or a suffix of it with at least two
    components (`VamsCLI/requirements.txt`), a path relative to the installing file, an absolute or
    unrelated-prefix path whose parent directory name contains the listed project's directory name
    (`/opt/vams/vamscli-src/requirements.txt` for `tools/VamsCLI`, compared lower-case without
    punctuation), or the bare name where the lines just above name the project's directory
    (working-directory, WORKDIR, cd). Backslash-continued shell lines are joined first.

    Known gaps, documented in the developer setup guide: a directory COPY followed by `-r` on a path
    under another name (`COPY tools/VamsCLI /src` then `-r /src/requirements.txt`), a path assembled in
    code (`path.join('tools', 'VamsCLI', 'requirements.txt')`), and a bare name in a file of another
    directory. The package-name check against the lock still bounds what such an install can contain.
    """
    base = os.path.basename(target)
    directory = os.path.dirname(target)
    project_flat = _flat(os.path.basename(directory))
    found = []
    for rel in tracked:
        if not INSTALLER_FILE.search(rel) or INSTALLER_SKIP.search(rel) or rel == target:
            continue
        try:
            with open(os.path.join(root, rel), encoding="utf-8") as handle:
                text = handle.read()
        except (OSError, UnicodeDecodeError):
            continue
        if base not in text:
            continue
        lines = text.splitlines()
        for index, line in logical_lines(text):
            if base not in line or not INSTALL_VERB.search(line):
                continue
            nearby = "\n".join(lines[max(0, index - 12) : index + 1])
            for token in re.split(r"[\s'\"=,:()`]+", line):
                if os.path.basename(token) != base:
                    continue
                parent = os.path.dirname(token)
                parts = [part for part in parent.split("/") if part not in ("", ".", "..")]
                resolved = os.path.normpath(os.path.join(os.path.dirname(rel), token))
                suffix = "/".join(parts[-1:] + [base]) if parts else ""
                if (
                    token.lstrip("./").endswith(target)
                    or resolved == target
                    or (len(parts) >= 1 and target.endswith("/" + suffix) and len(suffix.split("/")) >= 2)
                    or (project_flat and parts and project_flat in _flat(parts[-1]))
                    or (not parent and directory in nearby)
                ):
                    found.append((rel, index + 1))
                    break
    return found


def check_ranged_inputs(root, tracked, lock_dirs):
    """Validate `rangedInputs` and return its paths; fail closed on anything that could hide an install.

    Each entry needs a reason, must be a tracked file beside a uv.lock, every distribution it names must
    be a package of that lock, and nothing may install or copy it (a Dockerfile, an AMI recipe, a
    workflow, a script or CDK bundling code): such a file would be installed without being audited.
    """
    try:
        with open(os.path.join(root, EXEMPTIONS_PATH), encoding="utf-8") as handle:
            data = json.load(handle)
    except (OSError, ValueError) as exc:
        raise AuditError(f"{EXEMPTIONS_PATH} is not readable JSON: {exc}")
    entries = data.get("rangedInputs", []) if isinstance(data, dict) else []
    tracked_set = set(tracked)
    problems = []
    paths = set()
    for entry in entries:
        path = entry.get("path") if isinstance(entry, dict) else None
        if not isinstance(path, str) or not path.strip():
            problems.append(f"an entry has no path: {entry!r}")
            continue
        paths.add(path)
        if not str(entry.get("reason", "")).strip():
            problems.append(f"{path}: no reason")
        directory = os.path.dirname(path) or "."
        if path not in tracked_set:
            problems.append(f"{path}: not a tracked file any more; remove the entry")
            continue
        if directory not in lock_dirs:
            problems.append(f"{path}: has no uv.lock beside it; it is not a ranged input")
            continue
        if os.path.basename(path).startswith("requirements") or os.path.basename(path) == "setup.py":
            with open(os.path.join(root, path), encoding="utf-8") as handle:
                declared = requirement_names(path, handle.read())
            with open(os.path.join(root, directory, "uv.lock"), encoding="utf-8") as handle:
                locked = locked_names(handle.read())
            missing = sorted(declared - locked)
            if not declared:
                problems.append(f"{path}: no distributions found in it (is it a dependency file?)")
            if missing:
                problems.append(f"{path}: names not in {directory}/uv.lock: {', '.join(missing)}")
        if os.path.basename(path).startswith("requirements"):
            for rel, line in installers_of(root, tracked, path):
                problems.append(f"{path}: installed or copied by {rel}:{line}, so it is not an unaudited input")
    if problems:
        raise AuditError(f"{EXEMPTIONS_PATH} rangedInputs is invalid:\n  " + "\n  ".join(problems))
    return paths


# A requirement installed from a direct URL (`name @ https://...`, or a git URL). pip-audit cannot audit one
# (it has no version to look up), so the audit hands it the rest of the file and reports these by name.
URL_REQUIREMENT = re.compile(r"^([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[^\]]*\])?\s*@\s*\S+")
NOT_AUDITED = []  # (export path, package name)


def split_url_requirements(text):
    """(text without the direct-URL requirement entries, their names). An entry is its line and the indented
    continuation lines (hashes) below it."""
    kept, names, skipping = [], [], False
    for line in text.splitlines(keepends=True):
        if line[:1] in (" ", "\t") and (skipping or kept):
            if not skipping:
                kept.append(line)
            continue
        match = URL_REQUIREMENT.match(line)
        skipping = bool(match)
        if match:
            names.append(canonical_name(match.group(1)))
        else:
            kept.append(line)
    return "".join(kept), names


def audit_export(root, rel_path, pip_audit):
    """Findings for one requirements file: list of (package, version, [ids])."""
    with open(os.path.join(root, rel_path), encoding="utf-8") as handle:
        filtered, url_names = split_url_requirements(handle.read())
    temp_filtered = None
    audited_path = rel_path
    if url_names:
        NOT_AUDITED.extend((rel_path, name) for name in url_names)
        handle_fd, temp_filtered = tempfile.mkstemp(prefix="uv-export-nourl-", suffix=".txt")
        with os.fdopen(handle_fd, "w", encoding="utf-8") as handle:
            handle.write(filtered)
        audited_path = temp_filtered
    try:
        return _audit_file(root, audited_path, rel_path, pip_audit)
    finally:
        if temp_filtered:
            os.unlink(temp_filtered)


def _audit_file(root, rel_path, shown_path, pip_audit):
    command = pip_audit + ["-r", rel_path, "-f", "json"] + PIP_AUDIT_STRICT_ARGS
    result = run(command, root, check=False)
    try:
        report = json.loads(result.stdout)
    except ValueError:
        raise AuditError(
            f"pip-audit gave no readable result for {shown_path} (exit {result.returncode}); "
            f"the advisory service may be unreachable: {last_line(result.stderr)}"
        )
    findings = []
    for dep in report.get("dependencies", []):
        if "skip_reason" in dep:
            raise AuditError(f"pip-audit skipped {dep.get('name')} in {shown_path}: {dep['skip_reason']}")
        for vuln in dep.get("vulns", []):
            ids = [vuln["id"]] + list(vuln.get("aliases") or [])
            findings.append((dep["name"], dep["version"], ids))
    if result.returncode not in (0, 1) or (result.returncode == 1 and not findings):
        raise AuditError(f"pip-audit failed for {shown_path} (exit {result.returncode}): {last_line(result.stderr)}")
    return findings


def audit():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--root", default=".", help="repository root (default: current directory)")
    parser.add_argument("--today", help="override today's date (YYYY-MM-DD), for tests")
    args = parser.parse_args()
    root = os.path.abspath(args.root)
    today = datetime.date.fromisoformat(args.today) if args.today else datetime.date.today()

    version = os.environ.get("PIP_AUDIT_VERSION", "").strip()
    if not re.match(r"^\d+(\.\d+)+$", version):
        error("pip-audit", "PIP_AUDIT_VERSION must be set to an exact version")
        return 2
    pip_audit = ["uvx", f"pip-audit=={version}"]
    # A fresh cache directory per run: a cached response must never stand in for the live advisory service.
    pip_audit += ["--cache-dir", tempfile.mkdtemp(prefix="pip-audit-cache-")]

    errors = []
    try:
        allowlist = load_allowlist(root, today)
    except AuditError as exc:
        error("Python audit allowlist", exc)
        return 1

    try:
        tracked = tracked_files(root)
    except AuditError as exc:
        error("Python audit", f"{root} is not a git checkout the audit can list: {last_line(exc)}")
        return 1
    lock_dirs = sorted({os.path.dirname(p) or "." for p in tracked if os.path.basename(p) == "uv.lock"})
    if not lock_dirs:
        error("Python audit", "no tracked uv.lock found; the discovery is broken")
        return 1
    print(f"Found {len(lock_dirs)} uv.lock project(s): {', '.join(lock_dirs)}")

    try:
        ranged_inputs = check_ranged_inputs(root, tracked, set(lock_dirs))
    except AuditError as exc:
        error("Python lock exemptions", exc)
        return 1

    all_findings = []  # (project, package, version, ids)
    for project in lock_dirs:
        project_dir = os.path.join(root, project)
        print(f"::group::{escape_data(project)}")
        try:
            run(["uv", "lock", "--check"], project_dir)
            exports = []
            for path in tracked_files(project_dir):
                if "/" in path or not REQUIREMENTS_FILE.match(path):
                    continue
                if os.path.join(project, path).replace(os.sep, "/") in ranged_inputs:
                    continue
                flags = read_export_command(os.path.join(project_dir, path))
                if flags is None:
                    raise AuditError(
                        f"{project}/{path} is not a uv export (no `uv export` header), so it is neither checked "
                        f"against {project}/uv.lock nor audited. Regenerate it with `uv export ... -o {path}` "
                        f"or remove it."
                    )
                exports.append((path, flags))
            temp_export = None
            for path, flags in exports:
                with open(os.path.join(project_dir, path), "rb") as handle:
                    committed = handle.read()
                run(["uv", "export"] + flags + ["-o", path], project_dir)
                with open(os.path.join(project_dir, path), "rb") as handle:
                    regenerated = handle.read()
                if regenerated != committed:
                    raise AuditError(
                        f"{project}/{path} is stale: it differs from `uv export` of {project}/uv.lock. "
                        f"Regenerate it with the command in its header and commit it."
                    )
            # Every committed export, plus what the lock resolves with every group and extra: a dev
            # extra or group that no committed export names is installed by CI and must be audited too.
            to_audit = [os.path.join(project, path) for path, _ in exports]
            handle, temp_export = tempfile.mkstemp(prefix="uv-export-", suffix=".txt")
            os.close(handle)
            run(
                [
                    "uv",
                    "export",
                    "--frozen",
                    "--no-hashes",
                    "--no-emit-project",
                    "--no-emit-local",
                    "--no-annotate",
                    "--all-groups",
                    "--all-extras",
                    "-o",
                    temp_export,
                ],
                project_dir,
            )
            to_audit.append(temp_export)
            for rel in to_audit:
                for package, pkg_version, ids in audit_export(root, rel, pip_audit):
                    all_findings.append((project, package, pkg_version, ids))
            if temp_export:
                os.unlink(temp_export)
        except AuditError as exc:
            errors.append(str(exc))
            error(f"Python audit ({project})", exc)
        print("::endgroup::")

    # Apply the allowlist; an entry that matches nothing is stale.
    used = set()
    blocking = []
    for project, package, pkg_version, ids in all_findings:
        match = None
        for index, entry in enumerate(allowlist):
            if canonical_name(entry["package"]) == canonical_name(package) and entry["id"] in ids:
                match = index
                break
        if match is None:
            blocking.append((project, package, pkg_version, ids))
        else:
            used.add(match)
    stale = [e for i, e in enumerate(allowlist) if i not in used]

    summary = [
        "## Python dependency audit",
        "",
        f"Projects: {len(lock_dirs)}. Findings: {len(all_findings)}. Allowlisted: {len(all_findings) - len(blocking)}.",
        "",
    ]
    if NOT_AUDITED:
        listed = ", ".join(sorted({name for _, name in NOT_AUDITED}))
        summary += [f"Not audited (installed from a direct URL, which pip-audit cannot check): {listed}.", ""]
    if blocking:
        summary += ["| Project | Package | Version | Advisory |", "| --- | --- | --- | --- |"]
        # One row per (project, package, version, advisory): an export and its dev export can both list it.
        rows = {}
        for project, package, pkg_version, ids in blocking:
            rows.setdefault((project, package, pkg_version, ids[0]), ids)
        for (project, package, pkg_version, _), ids in sorted(rows.items()):
            summary.append(f"| {project} | {package} | {pkg_version} | {ids[0]} |")
            error("Python advisory", f"{package} {pkg_version} in {project}: {', '.join(ids)}")
        summary.append("")
        summary.append(
            "Fix by bumping the package in the project's pyproject.toml and re-locking, "
            "or add a reasoned entry to the allowlist."
        )
    for entry in stale:
        message = f"allowlist entry {entry['id']} ({entry['package']}) matches no current finding; remove it"
        errors.append(message)
        error("Python audit allowlist", message)
        summary.append(f"- Stale allowlist entry: {entry['id']} ({entry['package']})")
    if errors:
        summary.append("")
        summary.append(f"{len(errors)} check(s) failed; see the job log.")
    if not blocking and not errors:
        summary.append("No blocking findings.")
    target = os.environ.get("GITHUB_STEP_SUMMARY")
    if target:
        with open(target, "a", encoding="utf-8") as handle:
            handle.write("\n".join(summary) + "\n")
    print("\n".join(summary))
    return 1 if (blocking or errors) else 0


def main():
    try:
        return audit()
    except AuditError as exc:
        error("Python audit", exc)
        return 1


if __name__ == "__main__":
    sys.exit(main())
